// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 430;
draw.viewbox(0, 0, W, H);

var currentTheta1 = 35;
var currentRatio = 0.75;
var currentStep = 0;

var teal = '#007fa7';
var blueFill = '#d9edf5';
var blueStroke = '#75b7cf';
var dark = '#111';
var criticalColor = '#555';
var tirColor = '#b4463a';

var stage = draw.group();

var arrow = draw.marker(12, 12, function (add) {
  add.path('M 1 1 L 11 6 L 1 11 z').fill(teal);
});
arrow.ref(10, 6).orient('auto');

var dashedArrow = draw.marker(12, 12, function (add) {
  add.path('M 1 1 L 11 6 L 1 11 z').fill(criticalColor);
});
dashedArrow.ref(10, 6).orient('auto');

function degToRad(a) { return a * Math.PI / 180; }
function polarPoint(cx, cy, r, aDeg) {
  var a = degToRad(aDeg);
  return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) };
}
function arcPath(cx, cy, r, a1, a2) {
  var p1 = polarPoint(cx, cy, r, a1);
  var p2 = polarPoint(cx, cy, r, a2);
  var delta = a2 - a1;
  var large = Math.abs(delta) > 180 ? 1 : 0;
  var sweep = delta >= 0 ? 1 : 0;
  return 'M ' + p1.x + ' ' + p1.y + ' A ' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + p2.x + ' ' + p2.y;
}
function labelText(parent, str, x, y, size, anchor, fill) {
  return parent.text(str)
    .font({ family: 'sans-serif', size: size || 16, anchor: anchor || 'middle' })
    .fill(fill || dark)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' })
    .center(x, y);
}
function addTooltip(el, tip, title, body) {
