}

function caseInfo(theta1, ratio) {
  var thetaC = Math.asin(ratio) * 180 / Math.PI;
  var tol = 0.65;
  if (Math.abs(theta1 - thetaC) <= tol) {
    return { kind: 'critical', thetaC: thetaC, theta2: 90 };
  }
  if (theta1 > thetaC) {
    return { kind: 'tir', thetaC: thetaC, theta2: null };
  }
  return { kind: 'refraction', thetaC: thetaC, theta2: Math.asin(Math.sin(degToRad(theta1)) / ratio) * 180 / Math.PI };
}

function renderFigure() {
  stage.clear();

  var P = { x: 300, y: 185 };
  var top = 35;
  var boundaryY = P.y;
  var bottomY = 355;
  var leftX = 55;
  var rightX = 545;
