    .stroke({ color: '#333', width: 1.2, dasharray: '7 5' });

  labelText(bg, 'n₂', 92, 70, 18, 'middle');
  labelText(bg, 'n₁', 503, 210, 18, 'middle');

  var thetaC = info.thetaC;
  var L = 168;

  var critStart = polarPoint(P.x, P.y, L, 90 + thetaC);
  var critRay = drawRay(stage, critStart.x, critStart.y, P.x, P.y, {
    color: criticalColor,
    width: 2,
    dasharray: '8 6',
    marker: dashedArrow,
    opacity: 0.78
  });
  addTooltip(
    critRay,
    'Dashed reference: the critical incident direction θc.',
    'Critical-angle reference',
    'This dashed ray marks the angle where sin(θc)=n₂/n₁. If the solid incident ray is farther from the normal than this reference, transmission into n₂ is no longer possible.'
  );

  var incStart = polarPoint(P.x, P.y, L, 90 + currentTheta1);
  var reflEnd = polarPoint(P.x, P.y, L, 90 - currentTheta1);

  var incRay = drawRay(stage, incStart.x, incStart.y, P.x, P.y);
  addTooltip(
    incRay,
    'Incident ray in the higher-index medium n₁.',
    'Incident ray',
    'The incident angle θ₁ is measured from the dashed normal, not from the surface. Increasing θ₁ pushes the refracted ray farther away from the normal.'
