    addTooltip(
      refrRay,
      info.kind === 'critical' ? 'At θc, the refracted ray is tangent to the boundary.' : 'Refracted ray in n₂ bends away from the normal.',
      'Refracted ray',
      'Because n₁ is larger than n₂, Snell’s law requires θ₂ to be larger than θ₁. At the critical angle θ₂ reaches 90°, the largest possible transmitted angle.'
