  currentTheta1 = v;
  renderFigure();
}
function update_indexRatio(v) {
  currentRatio = v;
  renderFigure();
}

var demoSteps = [
  {
    title: 'Ordinary refraction',
    narration: 'With θ₁ below θc, part of the light reflects back into n₁ and part refracts into n₂. Because n₁ is greater than n₂, the refracted ray bends away from the normal.',
    state: { incidentAngle: 35, indexRatio: 0.75 }
  },
