  parent.path(arcPath(P.x, P.y, 73, 90, 130))
    .fill('none')
    .stroke({ color: dark, width: 1.15, linecap: 'round' });
  var pc = pointOn(P.x, P.y, 92, 110);
  labelText(parent, 'θc', pc.x, pc.y + 3, 18, 'middle');

  labelLeft(parent, 'Total', x + 157, 158, 19);
  labelLeft(parent, 'internal', x + 157, 181, 19);
  labelLeft(parent, 'reflection', x + 157, 204, 19);

  labelPlain(parent, '(c)', x + panelW / 2, 306, 19, 'middle');
}

function drawAll() {
  stage.clear();
  highlights = [];

  drawPanelA(stage, panels[0].x);
  drawPanelB(stage, panels[1].x);
  drawPanelC(stage, panels[2].x);

  var hLayer = stage.group();
  for (var i = 0; i < panels.length; i++) {
    var r = hLayer.rect(panelW + 10, bottomY - topY + 12)
      .move(panels[i].x - 5, topY - 6)
      .radius(3)
      .fill({ color: '#fff5c4', opacity: 0 })
      .stroke({ color: '#e7ad3a', width: 0, opacity: 0 });
    r.css('pointer-events', 'none');
    highlights.push(r);
  }
  updateHighlight();
}

function regimeForAngle(v) {
  if (Math.abs(v - thetaC) <= 0.5) return 1;
  return v < thetaC ? 0 : 2;
}

function updateHighlight() {
  if (!highlights.length) return;
  var active = regimeForAngle(currentTheta1);
  for (var i = 0; i < highlights.length; i++) {
    if (i === active) {
      highlights[i]
        .fill({ color: '#fff5c4', opacity: 0.045 })
        .stroke({ color: '#e7ad3a', width: 1.35, opacity: 0.55 });
    } else {
      highlights[i]
        .fill({ color: '#fff5c4', opacity: 0 })
        .stroke({ color: '#e7ad3a', width: 0, opacity: 0 });
    }
  }
}

function manualNarration(v) {
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (!n || !l) return;
  if (regimeForAngle(v) === 0) {
    n.textContent = 'θ₁ = ' + v + '° is below the critical angle, so panel (a) is selected: light partly reflects and partly refracts into n₂.';
    l.textContent = 'Below θc: ordinary refraction';
  } else if (regimeForAngle(v) === 1) {
    n.textContent = 'θ₁ = ' + v + '° is the critical angle, so panel (b) is selected: the refracted ray just reaches the boundary direction, θ₂ = 90°.';
    l.textContent = 'At θc: critical angle';
  } else {
    n.textContent = 'θ₁ = ' + v + '° is beyond the critical angle, so panel (c) is selected: no refracted ray is possible and the ray totally internally reflects.';
    l.textContent = 'Above θc: total internal reflection';
  }
}

function update_incidentAngle(v) {
  currentTheta1 = v;
  updateHighlight();
  manualNarration(v);
}

var demoSteps = [
  {
    title: 'Ordinary refraction',
    narration: 'Panel (a) stays visible in the triptych while it is highlighted: the incident ray partly reflects and partly refracts into n₂, bending away from the normal.',
    state: { incidentAngle: 35 }
  },
  {
    title: 'Critical angle',
    narration: 'Panel (b) is highlighted at the threshold case. The refracted ray lies exactly along the boundary, so the diagram shows θ₂ = 90° and the right-angle marker.',
    state: { incidentAngle: 49 }
  },
  {
    title: 'Total internal reflection',
    narration: 'Panel (c) is highlighted after θ₁ exceeds the critical angle. The refracted ray is absent, and the light remains in n₁ as a reflected ray.',
    state: { incidentAngle: 65 }
  }
];

function applyStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[currentStep];
  var a = step.state.incidentAngle;

  document.getElementById('incidentAngleInput').value = a;
  document.getElementById('incidentAngleVal').value = a;
  currentTheta1 = a;
  updateHighlight();

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;
}

function nextStep() { applyStep(currentStep + 1); }
function prevStep() { applyStep(currentStep - 1); }

drawAll();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

